 $importer->confirm($json,$p['signature']);$check(count($store->snapshot())===3,'Only accepted responses stored');$check(count($review->listing(TRUE))===2,'Only eligible requests pending');$check($pub->publicData()===$initial,'Import does not publish');
 try{$importer->confirm($json,$p['signature']);throw new LogicException('Stale import accepted');}catch(RuntimeException $e){$check(TRUE,'Concurrent stale preview denied');}
