 $doc=$writer->read($db->select('lit_contribution_publication','p')->fields('p',['file_hash'])->execute()->fetchField());$check(array_sum(array_column($doc['aggregate']['groups'],'response_count'))===10002,'Union counts each accepted submission once');$bytes=json_encode($doc);$check(!str_contains($bytes,'@') && !str_contains($bytes,'response_id') && !str_contains($bytes,'SAMPLE_'),'Public aggregate privacy');
