 $r=$review->get((int)$rows[0]['id']);$review->decide((int)$r['id'],'rejected','Isolated rejection',$r['fingerprint']);$p=$importer->preview([$changed]);$importer->confirm([$changed],$p['signature']);$check($review->get((int)$r['id'])['status']==='rejected','Identical reupload preserves rejection');$check($importer->preview([$earlier])['counts']['duplicate_email']===1,'Rejected response still reserves email');
 $fresh=$json[0];$fresh['response_id']='FRESH';$fresh['email']='fresh@example.org';$bad=$fresh;$bad['answers']['county_geoid']='99999';$p=$importer->preview([$bad]);$importer->confirm([$bad],$p['signature']);$check($importer->preview([$fresh])['counts']['new']===1,'Invalid row never reserves email');
 $same=$fresh;$same['response_id']='AAA';$same['submitted_at']='2020-01-01T00:00:00+00:00';$p=$importer->preview([$fresh,$same]);$check($p['accepted'][0]['key']==='LIT_UPLOAD_SAMPLE_V1/AAA' && $p['counts']['duplicate_email']===1,'Submission time beats file order');
 $p=$importer->preview([$fresh,$fresh]);$check($p['counts']['invalid']===2 && !$p['accepted'],'Repeated source IDs rejected');
 $withdraw=$json[1];$withdraw['answers']['aggregate_permission']='no';$p=$importer->preview([$withdraw]);$importer->confirm([$withdraw],$p['signature']);$check(count($review->listing(TRUE))===0,'Permission withdrawal excluded from eligible pending queue');$check($pub->publish()['included']===10000,'Permission withdrawal removes prior approved contribution');
 $address=$fresh;$address['email']='fictional@example.test';$check($validator->normalize($address,FALSE)['email']==='fictional@example.test','Operational adapter accepts normal non-mock email domains');try{$validator->normalize($address);throw new LogicException('Mock domain restriction lost');}catch(UnexpectedValueException $e){$check(TRUE,'Mock adapter retains synthetic email restriction');}
 $token=$store->stage([$fresh],(int)$owner->id());$check($store->staged($token,(int)$owner->id())===[$fresh],'Private staging roundtrip');try{$store->staged($token,999999);throw new LogicException('Cross-user preview');}catch(RuntimeException $e){$check(TRUE,'Preview actor bound');}$store->discard($token);
 foreach([['{}','json'],[str_repeat('x',2097153),'csv'],[json_encode(['export_version'=>1,'submissions'=>array_fill(0,1001,$fresh)]),'json']] as [$b,$f]){try{$mapper->decode($b,$f);throw new LogicException('Invalid input allowed');}catch(InvalidArgumentException $e){$check(TRUE,'Invalid envelope/size/count rejected');}}
 // Exercise the actual confirmation submit handler with isolated service storage.
 $formRow=$fresh;$formRow['response_id']='FORM_ONLY';$formRow['email']='form-only@example.org';$p=$importer->preview([$formRow]);unset($p['accepted']);
 $state=new \Drupal\Core\Form\FormState();$state->set('stage_token',$store->stage([$formRow],(int)$owner->id()))->set('preview',$p);$button=['#mode'=>'confirm'];$state->setTriggeringElement($button);
 $container=\Drupal::getContainer();$liveStore=$container->get('lit_contribution.export_store');$liveImporter=$container->get('lit_contribution.importer');$container->set('lit_contribution.export_store',$store);$container->set('lit_contribution.importer',$importer);
 try{$form=[];(new \Drupal\lit_contribution\Form\ImportForm())->submitForm($form,$state);$check(isset($store->snapshot()['LIT_UPLOAD_SAMPLE_V1/FORM_ONLY']),'Actual confirmation form writes isolated source');$check(count($review->listing(TRUE))===1,'Confirmation form creates eligible pending request');}finally{$container->set('lit_contribution.export_store',$liveStore);$container->set('lit_contribution.importer',$liveImporter);}
 $good=$pub->publicData();$broken=new class($root.'/web') extends AtomicAggregateWriter{public function write(array $d):string{throw new RuntimeException('Injected write failure');}};$failed=new Publication($db,$source,$validator,$review,$broken,\Drupal::service('lit_map.survey_normalizer'),$account);try{$failed->publish();throw new LogicException('Write succeeded');}catch(RuntimeException $e){$check($pub->publicData()===$good,'Failure retains last publication');}
